// Content-Security-Policy for both runtimes (security audit 2026-11-05, F14, F15 and D1).
//
//   script-src carries no 'unsafe-inline': the site's few inline scripts are allowed by their
//   sha256 (src/csp-hashes.js, generated by build-csp-hashes.mjs from the HTML pages), inline event
//   handlers are refused (script-src-attr 'none'), and the one third-party script, supabase-js, is
//   allowed by its exact URL (it also carries a Subresource Integrity hash, zerox-auth.js).
//   style-src allows the inline <style> blocks by hash as well. Two things stay looser, on purpose:
//   style attributes ('unsafe-inline' in style-src-attr only: the sign-in dialog of zerox-auth.js
//   is built with them, and a style attribute cannot run script), and on the two pages that open
//   the Razorpay checkout (pricing and the dashboard) style elements, because checkout.js adds
//   its own <style> to the page and its text cannot be hashed.
//   connect-src names the Supabase project's own origin when SUPABASE_URL is set, img-src only the
//   hosts that serve account avatars, and form-action allows the CLI's loopback callback on the
//   sign-in page only.
import { INLINE_SCRIPT_HASHES, INLINE_STYLE_HASHES } from './csp-hashes.js';

// zerox-auth.js loads exactly this file (SUPABASE_JS_VERSION there; check-pages.mjs keeps them equal).
export const SUPABASE_JS_SRC = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.117.2/dist/umd/supabase.js';
const STYLE_HOSTS = ['https://fonts.googleapis.com', 'https://api.fontshare.com', 'https://cdn.fontshare.com'];
const FONT_HOSTS = ['https://fonts.gstatic.com', 'https://cdn.fontshare.com'];
// Where account avatars come from (the Google and GitHub sign-in providers).
const AVATAR_HOSTS = ['https://lh3.googleusercontent.com', 'https://avatars.githubusercontent.com'];
const RAZORPAY_FRAMES = ['https://api.razorpay.com', 'https://checkout.razorpay.com'];

const hashSource = hash => `'${hash}'`;

// The pages that open the Razorpay checkout (dashboard.js and pricing.js through billing-checkout.js):
// the pricing page, and the dashboard (also the root of the dashboard host). Static files answer the
// same on every host, so nothing but the page decides it.
export function opensCheckout({ hostname = '', pathname = '' } = {}) {
  const clean = String(pathname).replace(/\.html$/, '').replace(/\/$/, '');
  if (hostname === 'dashboard.zero-x.live' && (clean === '' || clean === '/index')) return true;
  return clean === '/pricing' || clean === '/dashboard';
}

export function supabaseOrigin(env = {}) {
  try {
    const url = new URL(String(env?.SUPABASE_URL || ''));
    if (url.protocol === 'https:' && url.hostname) return url.origin;
  } catch { /* not configured: the wildcard below */ }
  return 'https://*.supabase.co';
}

export function sitePolicy(env = {}, { hostname = '', pathname = '' } = {}) {
  const checkout = opensCheckout({ hostname, pathname });
  const loginPage = /^\/neuroncli\/login(\/|$)/.test(pathname);
  const styleSources = checkout
    ? ["'self'", "'unsafe-inline'", ...STYLE_HOSTS]
    : ["'self'", ...INLINE_STYLE_HASHES.map(hashSource), ...STYLE_HOSTS];
  return [
    "default-src 'self'",
    ['script-src', "'self'", ...INLINE_SCRIPT_HASHES.map(hashSource), SUPABASE_JS_SRC, 'https://checkout.razorpay.com'].join(' '),
    "script-src-attr 'none'",
    ['style-src', ...styleSources].join(' '),
    "style-src-attr 'unsafe-inline'",
    ['font-src', "'self'", 'data:', ...FONT_HOSTS].join(' '),
    ['img-src', "'self'", 'data:', ...AVATAR_HOSTS].join(' '),
    ['connect-src', "'self'", supabaseOrigin(env), 'https://api.razorpay.com', 'https://lumberjack.razorpay.com'].join(' '),
    checkout ? ['frame-src', ...RAZORPAY_FRAMES].join(' ') : "frame-src 'none'",
    "object-src 'none'",
    loginPage ? "form-action 'self' http://127.0.0.1:*" : "form-action 'self'",
    "frame-ancestors 'none'",
    "base-uri 'self'",
  ].join('; ');
}

// The operator pages: no inline script or style, nothing from another origin except the site fonts.
export const ADMIN_POLICY = [
  "default-src 'none'",
  "script-src 'self'",
  "script-src-attr 'none'",
  "style-src 'self'",
  "font-src 'self' https://cdn.fontshare.com https://fonts.gstatic.com",
  "img-src 'self'",
  "connect-src 'self'",
  "form-action 'none'",
  "frame-ancestors 'none'",
  "base-uri 'none'",
].join('; ');

// Powerful features the site never uses, switched off for every page.
export const PERMISSIONS_POLICY = 'camera=(), microphone=(), geolocation=(), usb=(), serial=(), bluetooth=(), interest-cohort=()';
// Keeps other sites' windows away from ours but lets a window we open (the payment popups) talk back.
export const CROSS_ORIGIN_OPENER_POLICY = 'same-origin-allow-popups';
